import{_ as a,o as i,c as t,ak as o}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"技术栈 / 个人技术积累","description":"","frontmatter":{},"headers":[],"relativePath":"pages/tech.md","filePath":"pages/tech.md"}'),e={name:"pages/tech.md"};function r(n,l,s,h,u,d){return i(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="技术栈-个人技术积累" tabindex="-1">技术栈 / 个人技术积累 <a class="header-anchor" href="#技术栈-个人技术积累" aria-label="Permalink to &quot;技术栈 / 个人技术积累&quot;">​</a></h1><blockquote><p>按模块划分，持续填充所学所掌握的知识</p></blockquote><h2 id="_1-编程语言" tabindex="-1">1. 编程语言 <a class="header-anchor" href="#_1-编程语言" aria-label="Permalink to &quot;1. 编程语言&quot;">​</a></h2><ul><li><strong>C/C++</strong>：面向对象、模块化封装</li><li><strong>Lua</strong>：时序脚本、Qt-C++/Lua 交互通信</li></ul><h2 id="_2-mcu-与裸机" tabindex="-1">2. MCU 与裸机 <a class="header-anchor" href="#_2-mcu-与裸机" aria-label="Permalink to &quot;2. MCU 与裸机&quot;">​</a></h2><ul><li><strong>平台</strong>：ST / LPC / GD32 / ESP32 等主流 MCU</li><li><strong>外设</strong>：CAN、UART、SPI、I2C、FLASH、EXMC</li><li><strong>框架</strong>：裸机事件驱动、前后台框架设计</li></ul><h2 id="_3-rtos" tabindex="-1">3. RTOS <a class="header-anchor" href="#_3-rtos" aria-label="Permalink to &quot;3. RTOS&quot;">​</a></h2><ul><li><strong>ThreadX</strong>：多任务、多线程协同</li><li><strong>UCOS III</strong>：任务调度、信号量、消息队列</li></ul><h2 id="_4-通信协议与分层架构" tabindex="-1">4. 通信协议与分层架构 <a class="header-anchor" href="#_4-通信协议与分层架构" aria-label="Permalink to &quot;4. 通信协议与分层架构&quot;">​</a></h2><ul><li><strong>总线</strong>：CAN、UART、FSMC 自定义协议</li><li><strong>协议栈</strong>：MCU 多节点/多协议/多链路自定义通信协议栈</li><li><strong>仪器分层</strong>：上位（人机）/ 中位（网关·编排·鉴权）/ 下位（实时执行·联锁）</li><li><strong>工程红线</strong>：禁止 UI 直连业务库与设备口；写操作走命令白名单与审计</li><li><strong>了解</strong>：CANopen、EtherCAT 协议栈原理</li></ul><h2 id="_5-bootloader" tabindex="-1">5. Bootloader <a class="header-anchor" href="#_5-bootloader" aria-label="Permalink to &quot;5. Bootloader&quot;">​</a></h2><ul><li>MCU-Bootloader 开发</li><li>STM32F103 / LPC5506 / APM32F407 Bootloader 实践</li></ul><h2 id="_6-电机控制" tabindex="-1">6. 电机控制 <a class="header-anchor" href="#_6-电机控制" aria-label="Permalink to &quot;6. 电机控制&quot;">​</a></h2><ul><li>步进/直流有刷电机常用驱动算法</li><li>梯形/S 形加减速</li><li>经典 PID 调控</li><li>卡尔曼滤波</li><li>电机多种模式状态控制、故障逻辑处理</li></ul><h2 id="_7-运动与算法" tabindex="-1">7. 运动与算法 <a class="header-anchor" href="#_7-运动与算法" aria-label="Permalink to &quot;7. 运动与算法&quot;">​</a></h2><ul><li>梯形加减速控制步进电机</li><li>多电机协同运动</li><li>闭环控制及失步检测</li><li>最小二乘法拟合曲线</li><li>快排处理数据、二分法优化</li></ul><h2 id="_8-pcb-设计" tabindex="-1">8. PCB 设计 <a class="header-anchor" href="#_8-pcb-设计" aria-label="Permalink to &quot;8. PCB 设计&quot;">​</a></h2><ul><li><strong>工具</strong>：PADS</li><li><strong>能力</strong>：绘制原理图、2/4 层板 PCB</li></ul><h2 id="_9-上位机与界面" tabindex="-1">9. 上位机与界面 <a class="header-anchor" href="#_9-上位机与界面" aria-label="Permalink to &quot;9. 上位机与界面&quot;">​</a></h2><ul><li>Qt C++/Lua 交互通信控制平台维护与完善</li><li>LVGL 简易界面</li><li>云端 OTA 开发经验</li></ul><h2 id="_10-图像与传感器" tabindex="-1">10. 图像与传感器 <a class="header-anchor" href="#_10-图像与传感器" aria-label="Permalink to &quot;10. 图像与传感器&quot;">​</a></h2><ul><li>数字摄像头</li><li>MCU 层面图像识别</li><li>灰度数据处理</li></ul><h2 id="_11-版本与协作" tabindex="-1">11. 版本与协作 <a class="header-anchor" href="#_11-版本与协作" aria-label="Permalink to &quot;11. 版本与协作&quot;">​</a></h2><ul><li>Git / SVN 版本控制；SVN→Git 全历史迁仓（<code>git svn</code>、authors 映射）</li><li>内网 GitLab CE（Omnibus）：Group/Project、分支保护、MR 流程、备份</li><li>Pingcode 项目管理工具</li><li>技术写作：VitePress 博客与操作/培训手册</li></ul><h2 id="_12-后端与内网-agent" tabindex="-1">12. 后端与内网 Agent <a class="header-anchor" href="#_12-后端与内网-agent" aria-label="Permalink to &quot;12. 后端与内网 Agent&quot;">​</a></h2><ul><li><strong>Web</strong>：Python · FastAPI · Uvicorn；静态 HTML/CSS/JS 同端口托管</li><li><strong>数据</strong>：SQLite；本地文件与备份策略</li><li><strong>AI 应用</strong>：TF-IDF RAG · OpenAI 兼容 LLM（可私有化 / mock）</li><li><strong>平台能力</strong>：多角色权限、多账号/SSO、知识库分类、问答/故障/评审/报告 Agent</li></ul>',26)])])}const _=a(e,[["render",r]]);export{g as __pageData,_ as default};
